parameters.text:
=Eres un ingeniero SRE. A partir de este informe JSON de diagnostico de ArgoCD, redacta un correo de diagnostico en espanol (con asunto y cuerpo), claro y accionable para el equipo. No inventes datos que no esten en el informe.

Informe:
{{ JSON.stringify($json) }}

parameters.jsCode:
const wh = ($('Webhook').first().json || {});
const body = wh.body || {};
const app = body.app || body.application || 'desconocida';

let report = {};
try { report = $('Diagnostico').first().json || {}; } catch (e) { report = {}; }

let llmText = '';
try {
  const out = $('LLM - redactar correo').first().json || {};
  llmText = out.text || out.response || out.output || '';
} catch (e) { llmText = ''; }

const signatures = Array.isArray(report.signatures) ? report.signatures.slice(0, 10) : [];
const lines = signatures.map((s) => `- [${s.category}] (x${s.count}) ${s.signature}`);
const fallback = [
  `Aplicacion ArgoCD: ${app}`,
  `health=${report.health || 'desconocido'} sync=${report.sync || 'desconocido'}`,
  `Recursos analizados: ${report.analyzedResources ?? '?'} | no saludables: ${report.unhealthyResources ?? '?'}`,
  '',
  'Firmas relevantes:',
  ...(lines.length ? lines : ['- (sin firmas)']),
].join('\n');

const llmUsed = Boolean(llmText && String(llmText).trim());
const bodyText = llmUsed ? llmText : fallback;

return [{ json: {
  to: 'sre@lab.test',
  subject: `[kubelab] Diagnostico ArgoCD: ${app}`,
  body: bodyText,
  llmUsed,
  application: app,
  health: report.health || null,
  sync: report.sync || null,
  signatureCount: report.signatureCount ?? null,
} }];
